INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-07-21' FROM countries WHERE name_en = 'China';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'en', 'Centralised clearance (Golden Tax System)', 'This deep-dive page reflects publicly available technical guidance as of July 2026 and is provided for general awareness, not legal or tax advice. Regional paper phase-out schedules, quota criteria, and sector-specific rollout detail continue to evolve — confirm current requirements directly with your local STA branch before building an integration.', 'China''s e-fapiao reform has run for a full decade before reaching nationwide status — this is a mature, carefully piloted system, not a rushed rollout.', 'The critical distinction to internalise: the XML is the legally binding document. Everything else — OFD, PDF — exists purely for human eyes.', 'A textbook clearance model: nothing is a legally valid invoice in China until the STA has validated and stamped it.', 'Access runs through a tax digital account rather than a single "registration" event — set expectations for an ongoing relationship with the platform, not a one-time signup.', 'China folds enforcement into its broader tax administration architecture rather than publishing a discrete e-invoicing penalty schedule.' FROM countries WHERE name_en = 'China';
INSERT INTO deep_dive_stats (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'China';
INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', 'XML', 'Legal source of truth');
