INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', 'Dec 2024', 'Nationwide since');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'China';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Legal source of truth', '[["Format", "Structured XML"], ["Human-readable rendering", "OFD (Open Fixed-layout Document) or PDF"], ["Legal weight", "XML only — OFD/PDF is for display purposes"]]', 'Fully digitalized e-fapiao specifically doesn''t require a specific digital format for legal validity — unlike the older "non-fully-digital" VAT e-fapiao, which had to be in OFD or PDF.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'China';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Invoice identification', '[["Invoice code", "Unique 20-digit number"], ["Structure", "Last 2 digits of year + provincial regional code + issuance channel digit + sequential code"], ["Added by", "STA upon clearance, alongside a QR code"]]', 'This structured numbering is deliberately decodable — the region and issuance channel are embedded directly in the invoice code itself.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'China';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Invoice quotas', '[["What it is", "A cap on invoices a taxpayer can issue"], ["Determined by", "Tax risk level, tax credit rating, actual business operations"], ["Adjustment", "Dynamic, based on ongoing behaviour"]]', 'This is a genuinely distinctive mechanism — your invoicing capacity itself is tied to your standing with the tax authority, functioning as a practical compliance incentive beyond any formal penalty.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 3 FROM countries WHERE name_en = 'China';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Archiving', '[["Standard retention", "10 years"], ["Certain voucher categories", "Up to 30 years"], ["What to keep", "Cleared XML plus QR code, invoice code/number, digital signature"]]', 'Confirm which retention tier applies to your specific voucher category — the gap between 10 and 30 years is significant enough to matter for archiving system design.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE name_en = 'China';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Delivery to the recipient', '[["Channels", "Tax digital account, email, platform link, QR code, or other agreed means"], ["No fixed method", "Fully digitalized e-fapiao allows flexible delivery"]]', 'This flexibility is a deliberate improvement over the older regime — it reduces delivery costs and administrative friction compared to requiring a fixed OFD/PDF handoff.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'China';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Tax digital accounts', '[["Who gets one", "Both issuer and recipient"], ["What it shows", "All issued/received e-fapiao, real-time"], ["Issuer visibility", "Can track whether the recipient has deducted VAT"]]', 'This real-time mutual visibility is unusual internationally — most clearance systems don''t give the issuer ongoing insight into what the recipient does with the invoice afterward.', NULL, NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'China';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Scope', '[["Transaction types", "B2B, B2G, and B2C"], ["Legacy formats", "Being progressively phased out"]]', 'Paper fapiao are on a genuine retirement path — check your specific region and sector''s cutover announcement rather than assuming a single nationwide date for everyone.', NULL, NULL, NULL);
INSERT INTO deep_dive_lifecycle_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE name_en = 'China';
INSERT INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 'en', 'The clearance flow', 'Every invoice passes through the same sequence:', 'The STA''s national platform (built on the Golden Tax System) adds the validation confirmation, unique Key ID, and QR code before the invoice can legally exist.');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 0, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', '1. Generate XML');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 1, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', '2. Submit to STA');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 2, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', '3. Validate + add Key ID/QR');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 3, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', '4. Return to issuer');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 4, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', '5. Deliver to recipient');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'China';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🎫 Quotas as the real enforcement lever', NULL, NULL, 'Rather than relying primarily on fines, China''s system ties your practical ability to issue invoices to your standing with the tax authority — a business with a poor tax risk profile or credit rating can find its invoicing capacity constrained directly.', NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'China';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '📜 The Golden Tax System''s long history', NULL, NULL, 'E-fapiao sits on top of the Golden Tax System''s third and fourth generations — this is infrastructure that''s been under continuous development for years, not a system built from scratch for e-invoicing alone.', NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'China';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🧾 Six fapiao types still exist', NULL, NULL, 'General VAT fapiao, special VAT fapiao, and fully digitalized versions of each currently coexist during the ongoing transition — confirm which type applies to your specific transaction category rather than assuming a single unified format applies everywhere yet.', NULL, NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 3 FROM countries WHERE name_en = 'China';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '📊 Pre-filled tax declarations ahead', NULL, NULL, 'The digitalized fapiao data is explicitly described as laying the foundation for a future pre-filled "one integrated form" for tax declaration — a direction worth watching if you operate in China long-term.', NULL, NULL);
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'China';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Set up your tax digital account', 'This is your ongoing interface with the national e-invoicing service platform — for inquiry, downloading, and tracking of your issued and received e-fapiao.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'China';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm STA-approved invoicing software', 'Your invoicing system needs to generate compliant structured XML — verify your ERP or billing platform''s e-fapiao module is current with STA specifications.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'China';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Understand your invoice quota', 'Check what quota has been assigned to your business and what factors (tax risk level, credit rating, business operations) are driving it — this is worth actively managing, not just monitoring.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'China';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Choose your delivery channels', 'Decide how you''ll deliver invoices to recipients — tax digital account, email, platform link, or QR code — since fully digitalized e-fapiao doesn''t mandate a single fixed method.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'China';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Set up tiered archiving', 'Confirm which of your voucher categories require 10 years of retention versus the extended 30-year tier, and build your archiving system around cleared XML plus the associated QR code, invoice code, and digital signature.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 5 FROM countries WHERE name_en = 'China';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Track your regional paper phase-out schedule', 'Check your local STA branch''s specific announcements — the transition away from paper is happening region by region and sector by sector, not on one uniform national date.');
INSERT INTO deep_dive_portals (country_id, url, sort_order) SELECT id, 'https://www.chinatax.gov.cn/eng/home.html', 0 FROM countries WHERE name_en = 'China';
INSERT INTO deep_dive_portal_translations (portal_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_portals), 'en', 'State Taxation Administration (STA)');
